        snprintf(address, sizeof(address), "%p", open ? instance(self)->ptr : nullptr); // ruby.h: ruby_snprintf
        return utf8("#<" + class_name(self) + (open ? std::string(" ") + address : std::string(" (closed)")) + ">");
